sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    // 1. Clean: remove all spaces, upper-case    
    var gstin = current.getValue('gstin').replace(/\s+/g, '').toUpperCase();
    current.setValue('gstin', gstin);
    var util = new GSTINUtil();
    // 2. Format + state code    
    var fmt = util.validateFormat(gstin);
    if (!fmt.valid) {
        gs.addErrorMessage('GSTIN ' + gstin + ' is not valid: ' + fmt.reason);
        current.setAbortAction(true);
        return;
    }
    // 3. Check digit    
    var chk = util.checkDigit(gstin);
    if (!chk.valid) {
        gs.addErrorMessage('GSTIN ' + gstin + ' is not valid: ' + chk.reason);
        current.setAbortAction(true);
        return;
    }
    // 4. State code + name from the GSTIN (AC 3)    
    var st = util.extractState(gstin);
    current.setValue('state_code', st.code);
    current.setValue('state', st.name);
})(current, previous);
